\section{Lemmas}\label{app: lemmas}

\begin{lemma}[Lemma 8 in \cite{an2025asgo}]\label{lemma: norm asgo}
For a symmetric positive definite matrix $\Lambda\in \R^{n\times n}$ and matrix $A\in \R^{m\times n}$, it holds that
\begin{align*}
    \|A\|_*\leq \sqrt{\|\Lambda\|_*}\|A\|_{\Lambda^{-1}}.
\end{align*}

\end{lemma}

\begin{lemma}\label{lemma: norm}
For a symmetric positive definite matrix $\Lambda\in \R^{n\times n}$ and matrix $A\in \R^{m\times n}$, it holds that
\begin{align}\label{eq: norm 1}
    &\|A\|_\F\leq \sqrt{\opnrom{\Lambda}}\|A\|_{\Lambda^{-1}},\\ \label{eq: norm 2}
    &\|A\|_\Lambda \leq \sqrt{\opnrom{\Lambda}} \|A\|_\F,\\ \label{eq: norm 3}
    &\|A\|_\Lambda \leq \sqrt{\|\Lambda\|_*} \opnrom{A}.
\end{align}
\end{lemma}
\begin{proof}

We first prove \Cref{eq: norm 1} and \Cref{eq: norm 2}.

Suppose the spectral decomposition of $\Lambda$ is $\Lambda=U\Sigma U^\top$, where $U$ is an orthogonal matrix, $\Sigma=\text{diag}(\sigma_1, \sigma_2, ..., \sigma_n)$, $\sigma_1\geq \sigma_2\geq ...\geq \sigma_n$ are the singular values of $\Lambda$. Denote $AU=B=(b_1\, b_2\, ...\, b_n)$, where $b_i$ is the $i$-th column of $B$. Then, we have
\begin{align*}
    \|A\|_\Lambda^2=\trace{A\Lambda A^\top}=\trace{AU\Sigma U^\top A^\top}=\trace{\Sigma B^\top B}=\sum_{i=1}^n \sigma_i\|b_i\|_2^2.
\end{align*}
Note that 
\begin{align*}
    \|A\|_\F^2=\sum_{i=1}^n \|b_i\|_2^2.
\end{align*}
Thus, we have
    \begin{align*}
        &\|A\|_\Lambda\leq \sqrt{\sigma_1}\|A\|_\F= \sqrt{\opnrom{\Lambda}}\|A\|_\F,
    \end{align*}
and
    \begin{align*}
        &\|A\|_\Lambda\geq \sqrt{\sigma_n}\|A\|_\F.
    \end{align*}
Note that $\sigma_n^{-1}=\opnrom{\Lambda^{-1}}$. Thus,
\begin{align}\label{eq: norm 2'}
    \|A\|_\F\leq \sqrt{\sigma_n^{-1}}\|A\|_\Lambda=\opnrom{\Lambda^{-1}}\|A\|_\Lambda.
\end{align}
Since \Cref{eq: norm 2'} holds for any $\Lambda$, we can define $\Lambda'=\Lambda^{-1}$ and get
\begin{align}
    \|A\|_\F\leq \opnrom{\Lambda'}\|A\|_{{\Lambda'}^{-1}}.
\end{align}
Thus, we proved \Cref{eq: norm 1} and \Cref{eq: norm 2}. For \Cref{eq: norm 3}, we can prove it with the following inequalities
    \begin{align*}
        \|A\|_\Lambda=\sqrt{\trace{A\Lambda A^\top} }=\sqrt{\trace{A^\top A\Lambda } }\leq \sqrt{\opnrom{A^\top A}\|\Lambda\|_*}=\sqrt{\|\Lambda\|_*} \opnrom{A}.
    \end{align*}
\end{proof}



\subsection*{Proof of \Cref{lemma: smooth}}
\begin{proof}
    If $f:\R^{m\times n}\to \R$ is 1-$\Lambda$-norm Lipschitz smooth with a positive definite matrix $\Lambda \in \R^{n\times n}$, then, for any $W, W'\in \R^{m\times n}$, we have
    \begin{align*}
        \|\nabla f(W)-\nabla f(W')\|_\F\leq& \sqrt{\opnrom{\Lambda}}\|\nabla f(W)-\nabla f(W')\|_{\Lambda^{-1}}\\
        \leq& \sqrt{\opnrom{\Lambda}}\|W-W'\|_{\Lambda}\\
        \leq& \opnrom{\Lambda}\|W-W'\|_\F
    \end{align*}
    where the first inequality is due to \Cref{eq: norm 1} in \Cref{lemma: norm}, the second inequality is the definition of the $\Lambda$-smoothness, and the third inequality is due to \Cref{eq: norm 2} in \Cref{lemma: norm}.
    Thus, $f$ is also $\|\Lambda\|_{{\rm op}}$ Frobenius norm Lipschitz smooth. 

    Moreover, we have 
    \begin{align*}
        \|\nabla f(W)-\nabla f(W')\|_*\leq& \sqrt{\|\Lambda\|_*}\|\nabla f(W)-\nabla f(W')\|_{\Lambda^{-1}}\\
        \leq& \sqrt{\|\Lambda\|_*}\|W-W'\|_{\Lambda}\\
        \leq& \|\Lambda\|_*\opnrom{W-W'}
    \end{align*}
    where the first inequality is due to \Cref{lemma: norm asgo}, the second inequality is the definition of the $\Lambda$-smoothness, and the third inequality is due to \Cref{eq: norm 3} in \Cref{lemma: norm}.
    Thus, $f$ is also $\|\Lambda\|_*$ spectral norm Lipschitz smooth. 
\end{proof}


\begin{lemma}\label{lemma:  momentum error}
    For $t=0,1,..., T$, $M_t$ and $W_t$ generated by \Cref{alg: muon}, defining  $C_0=\nabla f(W_0)$, and when $t>0$, $C_{t}=\beta C_{t-1}+ (1-\beta) \nabla f(W_t)=(1-\beta)\sum_{i=1}^t \beta^{t-i}\nabla f(W_i)+\beta^t\nabla f(W_0)$, we have
\begin{align*}
    \E[\|C_t-M_t\|_\F]\leq&\sqrt{\frac{1-\beta}{1+\beta}}\frac{\sigma}{\sqrt{B}}+\beta^t\frac{\sigma}{\sqrt{B}}.
\end{align*}
\end{lemma}

\begin{proof}
According to \Cref{ass: variance}, we have following relationship about $G_t$ and $\nabla f(W_t)$.
\begin{align}\nonumber
    \E[\|G_t-\nabla f(W_t)\|^2_\F]=&\E\qth{\nth{\frac{1}{B}\sum_{i=1}^B\nabla f(W_t; \xi_{t,i})-\nabla f(W_t)}^2_\F}\\ \nonumber
    =&\frac{1}{B^2}\sum_{i=1}^B\E[\|\nabla f(W_t; \xi_{t,i})-\nabla f(W_t)\|^2_\F]\\ \label{eq: 2 variance}
    \leq&\frac{\sigma^2}{B}
\end{align}
where the second equality is due to $\E[\nabla f(W_t; \xi_{t,i})]=\nabla f(W_t)$ and the last inequality is due to $\E\|\nabla f(W;\xi_{t,i})-\nabla f(W)\|_\F^2]\leq \sigma^2$.
Moreover, according to the Cauchy-Schwarz inequality, we have
\begin{align}\label{eq: variance}
    \E[\|G_t-\nabla f(W_t)\|_\F]\leq \sqrt{\E[\|G_t-\nabla f(W_t)\|^2_\F]}=\frac{\sigma}{\sqrt{B}}.
\end{align}
    Note that $M_0=G_0$, $M_{t}=\beta M_{t-1}+ (1-\beta) G_t=(1-\beta)\sum_{i=1}^t \beta^{t-i}G_i+\beta^t G_0$. Thus, we have
\begin{align*}
    \E[\|C_t-M_t\|_\F]\leq &(1-\beta)\E[\|\sum_{i=1}^t \beta^{t-i}(G_i-\nabla f(W_i))\|_\F]+\beta^t\E[\|G_0-\nabla f(W_0)\|_\F]\\
    \leq&\sqrt{(1-\beta)^2\E[\|\sum_{i=1}^t \beta^{t-i}(G_i-\nabla f(W_i))\|^2_\F]}+\beta^t\frac{\sigma}{\sqrt{B}}\\
    \leq&\sqrt{(1-\beta)^2\sum_{i=1}^t \beta^{t-i}\frac{\sigma^2}{B}}+\beta^t\frac{\sigma}{\sqrt{B}}\\
    \leq&\sqrt{\frac{1-\beta}{1+\beta}}\frac{\sigma}{\sqrt{B}}+\beta^t\frac{\sigma}{\sqrt{B}}
\end{align*}
where the second inequality is due to the Cauchy-Schwarz inequality and \Cref{eq: variance}, the third inequality is due to \Cref{eq: 2 variance}.
\end{proof}





\section{Nonconvex}\label{app: nonconvex}
\subsection{Proof of \Cref{thm: nonconvex}}
\begin{proof}
Set $\eta_t=\eta$. Since $f$ is $L$ Frobenius norm Lipschitz smooth, we have
\begin{align*}
    \E[f(W_t)-f(W_{t+1})]\geq& \E[\eta\langle\nabla f(W_t), U_tV_t^\top \rangle-\frac{L}{2}\eta^2\|U_tV_t^\top\|_\F^2]\\
    \geq& \E[\eta\langle M_t , U_tV_t^\top \rangle -\frac{r L}{2}\eta^2-\eta\langle \nabla f(W_t)-M_t , U_tV_t^\top\rangle]\\
    \geq& \E[\eta\langle M_t , U_tV_t^\top \rangle -\frac{r L}{2}\eta^2-\eta\| \nabla f(W_t)-M_t \|_\F \|U_tV_t^\top\|_\F]\\
    \geq& \E[\eta \|M_t\|_*-\frac{r L}{2}\eta^2-\eta\sqrt{r}\|\nabla f(W_t)-M_t\|_\F]\\
    \geq& \E[\eta \|\nabla f(W_t)\|_*-\frac{r L}{2}\eta^2-\eta(\sqrt{r}+1)\|\nabla f(W_t)-M_t\|_\F]\\
    \geq& \E[\eta \|\nabla f(W_t)\|_*-\frac{r L}{2}\eta^2-2\eta\sqrt{r}\|\nabla f(W_t)-M_t\|_\F].
\end{align*}
Then, we need to analyze and bound the error $\|\nabla f(W_t)-M_t\|_\F$.
Note that $M_0=G_0$, $M_{t}=\beta M_{t-1}+ (1-\beta) G_t=(1-\beta)\sum_{i=1}^t \beta^{t-i}G_i+\beta^t G_0$.
We can define $C_0=\nabla f(W_0)$, and when $t>0$, $C_{t}=\beta C_{t-1}+ (1-\beta) \nabla f(W_t)=(1-\beta)\sum_{i=1}^t \beta^{t-i}\nabla f(W_i)+\beta^t\nabla f(W_0)$. Then, according to \Cref{lemma:  momentum error}, we have
\begin{align*}
    \E[\|C_t-M_t\|_\F]
    \leq&\sqrt{\frac{1-\beta}{1+\beta}}\frac{\sigma}{\sqrt{B}}+\beta^t\frac{\sigma}{\sqrt{B}}.
\end{align*}
Moreover,  when $t>0$, we can note that
\begin{align*}
    &\E[\|\nabla f(W_t)-C_t\|_\F]\\
    =&\E[\|\nabla f(W_t)-(\beta C_{t-1}+(1-\beta)\nabla f(W_t))\|_\F]\\
    =&\E[\beta\|\nabla f(W_t)-C_{t-1}\|_\F]\\
    \leq&\E[\beta\|\nabla f(W_{t-1})-C_{t-1}\|_\F+\beta\|\nabla f(W_{t-1})-\nabla f(W_t)\|_\F]\\
    \leq&\E[\beta\|\nabla f(W_{t-1})-C_{t-1}\|_\F+\beta L\|W_{t-1}-W_t\|_\F]\\
    =&\E[\beta\|\nabla f(W_{t-1})-C_{t-1}\|_\F+\beta L \eta\|U_{t-1}V_{t-1}^\top\|_\F]\\
    \leq&\E[\beta\|\nabla f(W_{t-1})-C_{t-1}\|_\F+\beta L \eta \sqrt{r}]\\
    \leq&\beta^t\|\nabla f(W_0)-C_0\|_\F+\sum_{i=1}^t \beta^i L \eta \sqrt{r}\\
    \leq& \frac{\sqrt{r}\beta L \eta}{1-\beta}
\end{align*}
where the second inequality is due to \Cref{ass: smooth}.

Thus, we have
\begin{align*}
    &\E[\|\nabla f(W_t)-M_t\|_\F]\leq \E[\|C_t-M_t\|_\F+\|\nabla f(W_t)-C_t\|_\F]\leq \sqrt{\frac{1-\beta}{1+\beta}}\frac{\sigma}{\sqrt{B}}+\beta^t\frac{\sigma}{\sqrt{B}} + \frac{\sqrt{r}\beta L \eta}{1-\beta},
\end{align*}
and
\begin{align*}
    \E[f(W_t)-f(W_{t+1})]
    \geq& \E[\eta \|\nabla f(W_t)\|_*-\frac{rL}{2}\eta^2-2\eta\sqrt{r}\|\nabla f(W_t)-M_t\|_\F]\\
    \geq& \E[\eta \|\nabla f(W_t)\|_*-\frac{rL}{2}\eta^2-2\eta\sqrt{\frac{1-\beta}{1+\beta}}\frac{\sigma\sqrt{r}}{\sqrt{B}}-2\eta \beta^t\frac{\sigma\sqrt{r}}{\sqrt{B}}-\frac{2r\eta^2 \beta L}{1-\beta} ].
\end{align*}
Summing over $t=0,1,..., T-1$, we can get
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\E[\|\nabla f(W_t)\|_*]\leq \frac{1}{T\eta}\E[f(W_0)-f(W_T)]+\frac{L r\eta}{2}+\frac{2\sigma\sqrt{r(1-\beta)}}{\sqrt{(1+\beta)B}}+\frac{2\beta\sigma\sqrt{r}}{(1-\beta)T\sqrt{B}}+\frac{2r\eta \beta L}{1-\beta}. 
\end{align*}
Denote $\Delta=f(W_0)-f^*$ and set $\eta=\sqrt{\frac{(1-\beta)\Delta}{rTL}}$, we can get
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\E[\|\nabla f(W_t)\|_*]\leq \frac{\Delta}{T\eta}+\frac{L r\eta}{2}+\frac{2\sigma\sqrt{r(1-\beta)}}{\sqrt{(1+\beta)B}}+\frac{2\beta\sigma\sqrt{r}}{(1-\beta)T\sqrt{B}}+\frac{2r\eta \beta L}{1-\beta}.
\end{align*}
When $B=1$, we can set $1-\beta=\min\{\frac{\sqrt{L\Delta}}{\sigma\sqrt{T}},1\}$ and get
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\E[\|\nabla f(W_t)\|_*]\leq O(1)\pth{\sqrt[4]{\frac{r^2L\Delta\sigma^2}{T}}+\sqrt{\frac{rL\Delta}{T}}+\frac{\sqrt{r}\sigma^2}{\sqrt{L\Delta T}}}.
\end{align*}
Thus, we can find an $\epsilon$-nuclear norm stationary point of $f$ with a complexity of $O(r^2L\sigma^2\Delta\epsilon^{-4})$.
\end{proof}

\subsection{Proof of \Cref{thm: nonconvex nuclear smooth}}
\begin{proof}
Set $\eta_t=\eta$. Since $f$ is $L_*$ spectral norm Lipschitz smooth, we have
\begin{align*}
    \E[f(W_t)-f(W_{t+1})]\geq& \E[\eta\langle\nabla f(W_t), U_tV_t^\top \rangle-\frac{L_*}{2}\eta^2\|U_tV_t^\top\|_{{\rm op}}^2]\\
    \geq& \E[\eta\langle M_t , U_tV_t^\top \rangle -\frac{L_*}{2}\eta^2-\eta\langle \nabla f(W_t)-M_t , U_tV_t^\top\rangle]\\
    \geq& \E[\eta\langle M_t , U_tV_t^\top \rangle -\frac{L_*}{2}\eta^2-\eta\| \nabla f(W_t)-M_t \|_* \|U_tV_t^\top\|_{{\rm op}}]\\
    \geq& \E[\eta \|M_t\|_*-\frac{L_*}{2}\eta^2-\eta\|\nabla f(W_t)-M_t\|_*]\\
    \geq& \E[\eta \|\nabla f(W_t)\|_*-\frac{L_*}{2}\eta^2-2\eta\|\nabla f(W_t)-M_t\|_*].
\end{align*}
Then, we need to analyze and bound the error $\|\nabla f(W_t)-M_t\|_*$.
Note that $M_0=G_0$, $M_{t}=\beta M_{t-1}+ (1-\beta) G_t=(1-\beta)\sum_{i=1}^t \beta^{t-i}G_i+\beta^t G_0$.
We can define $C_0=\nabla f(W_0)$, and when $t>0$, $C_{t}=\beta C_{t-1}+ (1-\beta) \nabla f(W_t)=(1-\beta)\sum_{i=1}^t \beta^{t-i}\nabla f(W_i)+\beta^t\nabla f(W_0)$. Then, according to \Cref{lemma:  momentum error}, we have
\begin{align*}
    \E[\|C_t-M_t\|_*]\leq \sqrt{r}\E[\|C_t-M_t\|_\F]
    \leq&\sqrt{\frac{1-\beta}{1+\beta}}\frac{\sigma\sqrt{r}}{\sqrt{B}}+\beta^t\frac{\sigma\sqrt{r}}{\sqrt{B}}.
\end{align*}
Moreover,  when $t>0$, we can note that
\begin{align*}
    &\E[\|\nabla f(W_t)-C_t\|_*]\\
    =&\E[\|\nabla f(W_t)-(\beta C_{t-1}+(1-\beta)\nabla f(W_t))\|_*]\\
    =&\E[\beta\|\nabla f(W_t)-C_{t-1}\|_*]\\
    \leq&\E[\beta\|\nabla f(W_{t-1})-C_{t-1}\|_*+\beta\|\nabla f(W_{t-1})-\nabla f(W_t)\|_*]\\
    \leq&\E[\beta\|\nabla f(W_{t-1})-C_{t-1}\|_*+\beta L_*\|W_{t-1}-W_t\|_{{\rm op}}]\\
    =&\E[\beta\|\nabla f(W_{t-1})-C_{t-1}\|_*+\beta L_* \eta\|U_{t-1}V_{t-1}^\top\|_{{\rm op}}]\\
    \leq&\E[\beta\|\nabla f(W_{t-1})-C_{t-1}\|_*+\beta L_* \eta ]\\
    \leq&\beta^t\|\nabla f(W_0)-C_0\|_\F+\sum_{i=1}^t \beta^i L_* \eta \\
    \leq& \frac{\beta L_* \eta}{1-\beta}
\end{align*}
where the second inequality is due to \Cref{ass: nuclear smooth}.

Thus, we have
\begin{align*}
    &\E[\|\nabla f(W_t)-M_t\|_*]\leq \E[\|C_t-M_t\|_*+\|\nabla f(W_t)-C_t\|_*]\leq \sqrt{\frac{1-\beta}{1+\beta}}\frac{\sigma\sqrt{r}}{\sqrt{B}}+\beta^t\frac{\sigma\sqrt{r}}{\sqrt{B}} + \frac{\beta L_* \eta}{1-\beta},
\end{align*}
and
\begin{align*}
    \E[f(W_t)-f(W_{t+1})]
    \geq& \E[\eta \|\nabla f(W_t)\|_*-\frac{L_*}{2}\eta^2-2\eta\|\nabla f(W_t)-M_t\|_*]\\
    \geq& \E[\eta \|\nabla f(W_t)\|_*-\frac{L_*}{2}\eta^2-2\eta\sqrt{\frac{1-\beta}{1+\beta}}\frac{\sigma\sqrt{r}}{\sqrt{B}}-2\eta \beta^t\frac{\sigma\sqrt{r}}{\sqrt{B}}-\frac{2\eta^2 \beta L_*}{1-\beta} ].
\end{align*}
Summing over $t=0,1,..., T-1$, we can get
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\E[\|\nabla f(W_t)\|_*]\leq \frac{1}{T\eta}\E[f(W_0)-f(W_T)]+\frac{L_* \eta}{2}+\frac{2\sigma\sqrt{r(1-\beta)}}{\sqrt{(1+\beta)B}}+\frac{2\beta\sigma\sqrt{r}}{(1-\beta)T\sqrt{B}}+\frac{2\eta \beta L_*}{1-\beta}. 
\end{align*}
Denote $\Delta=f(W_0)-f^*$ and set $\eta=\sqrt{\frac{(1-\beta)\Delta}{TL_*}}$, we can get
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\E[\|\nabla f(W_t)\|_*]\leq \frac{\Delta}{T\eta}+\frac{L_* \eta}{2}+\frac{2\sigma\sqrt{r(1-\beta)}}{\sqrt{(1+\beta)B}}+\frac{2\beta\sigma\sqrt{r}}{(1-\beta)T\sqrt{B}}+\frac{2\eta \beta L_*}{1-\beta}.
\end{align*}
When $B=1$, we can set $1-\beta=\min\{\frac{\sqrt{L_*\Delta}}{\sigma\sqrt{rT}},1\}$ and get
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\E[\|\nabla f(W_t)\|_*]\leq O(1)\pth{\sqrt[4]{\frac{rL_*\Delta\sigma^2}{T}}+\sqrt{\frac{L_*\Delta}{T}}+\frac{r\sigma^2}{\sqrt{L_*\Delta T}}}.
\end{align*}
Thus, we can find an $\epsilon$-nuclear norm stationary point of $f$ with a complexity of $O(rL_*\sigma^2\Delta\epsilon^{-4})$.
\end{proof}





\subsection{Proof of \Cref{thm: nonconvex third}}


\begin{proof}

Denote $d=mn$, $J_t=\mathsf{vec}(U_tV_t^\top)^\top H_t \mathsf{vec}(U_tV_t^\top)$, $H_t=\nabla^2f_v(\mathsf{vec}(W_t))$, and $f_v(\mathsf{vec}(W_t))=f(W_t)$. Set $\eta_t=\eta$. Taking the Taylor expansion at $W_t$, we have
\begin{align}\nonumber
    f(W_{t+1})-f(W_t)=&\langle\nabla f(W_t), W_{t+1}-W_t \rangle+\frac{1}{2}\mathsf{vec}(W_{t+1}-W_t)^\top \nabla^2f_v(\mathsf{vec}(W_t))\mathsf{vec}(W_{t+1}-W_t)\\ \nonumber
    &+\frac{1}{6}\sum_{i,j,k=1}^d[\nabla^3f_v(\theta)]_{ijk}\mathsf{vec}(W_{t+1}-W_t)_i\mathsf{vec}(W_{t+1}-W_t)_j\mathsf{vec}(W_{t+1}-W_t)_k\\ \nonumber
    \leq & -\eta\langle\nabla f(W_t), U_tV_t^\top \rangle+\frac{\eta^2 J_t}{2}+\frac{s\eta^3\|\mathsf{vec}(U_tV_t^\top)\|_\F^3}{6}\\ \nonumber
    \leq & -\eta\langle\nabla f(W_t), U_tV_t^\top \rangle+\frac{\eta^2 J_t}{2}+\frac{s\eta^3r^{3/2}}{6}\\ \label{eq: J descent}
    =&-\eta\|\nabla f(W_t)\|_*+\frac{\eta^2 J_t}{2}+\frac{s\eta^3r^{3/2}}{6}
\end{align}
where $\theta\in \R^d$ can be some vectors between $\mathsf{vec}(W_t)$ and $\mathsf{vec}(W_{t+1})$, and the first inequality is due to \Cref{ass: third}.

Denote $J=\frac{1}{T}\sum_{t=0}^{T-1}J_t$. Summing over $t=0,1,..., T-1$, we can get
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\|\nabla f(W_t)\|_*\leq \frac{f(W_0)-f(W_T)}{T\eta}+\frac{\eta J}{2}+\frac{s\eta^2r^{3/2}}{6}.
\end{align*}
Denote $\Delta=f(W_0)-f^*$. 
In experiments, we found that usually $J>0$. When $J>0$ and set $\eta=\sqrt{\frac{2\Delta}{JT}}$, we can get
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\|\nabla f(W_t)\|_*\leq \sqrt{\frac{2J\Delta }{T}}+\frac{sr^{3/2} \Delta }{3JT}.
\end{align*}
Thus, when $J>0$, we can find an $\epsilon$-nuclear norm stationary point of $f$ with a complexity of $O(J\Delta\epsilon^{-2})$.

When $J\leq 0$, we have
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\|\nabla f(W_t)\|_*\leq \frac{\Delta}{T\eta}+\frac{s\eta^2r^{3/2}}{6}.
\end{align*}
We can set $\eta=\sqrt[3]{\frac{\Delta}{sTr^{3/2}}}$ and get
\begin{align*}
    \frac{1}{T}\sum_{t=0}^{T-1}\|\nabla f(W_t)\|_*\leq O\pth{\frac{\Delta^{2/3}s^{1/3}r^{1/2}}{T^{2/3}}}.
\end{align*}
Thus, when $J\leq 0$, we can find an $\epsilon$-nuclear norm stationary point of $f$ with a complexity of $O(s^{1/2}r^{3/4}\Delta\epsilon^{-3/2})$.
\end{proof}




\section{Star-Convex}\label{app: convex}

In this section, we first present the proof of \Cref{thm: convex_L*}. Then, we present an additional convergence analysis of Muon under \Cref{ass: smooth} and \Cref{ass: third} in \Cref{app: convex L} and \Cref{app: convex J} respectively.
\subsection{Proof of \Cref{thm: convex_L*}}
\begin{proof}

\textbf{Constant stepsize}

First, by the $L_*$ spectral norm Lipschitz smoothness of $f$, we have
    \begin{align}\nonumber
        f(W_{t+1})&\leq f(W_{t})+\langle\nabla f(W_{t}),W_{t+1}-W_{t}\rangle +\frac{L_*}{2}\|W_{t+1}-W_{t}\|_{{\rm op}}^2\\ \label{eq: convex L*}
        &=f(W_{t})-\eta_{t}\|\nabla f(W_{t})\|_*+\frac{L_*\eta_{t}^2}{2}
    \end{align}
Then, from the star-convex condition, we obtain
    \begin{align}\nonumber
        f(W_t)&\leq f^*+\langle\nabla f(W_t), W_t-W^*\rangle\\ \nonumber
        &\leq f^*+\|\nabla f(W_t)\|_*\|W_{t}-W^*\|_{{\rm op}}\\ \nonumber
        &\leq f^*+\|\nabla f(W_t)\|_*D_{{\rm op}}\\ \label{eq: star-convex}
        -\|\nabla f(W_t)\|_*&\leq -\frac{f(W_t)-f^*}{D_{{\rm op}}}
    \end{align}
    where we apply the Cauchy–Schwarz inequality in the second inequality, and  in the third inequality we use \Cref{ass: bounded}.

Set $\eta=\eta$ and combine \eqref{eq: convex L*} and \eqref{eq: star-convex}. We have
\begin{align*}
    f(W_{t+1})-f^*\leq \pth{1-\frac{\eta}{D_{{\rm op}}}}( f(W_{t})-f^*)+\frac{\eta^2 L_*}{2},
\end{align*}
and
    \begin{align*}
        f(W_{T})-f^*\leq& \pth{1-\frac{\eta}{D_{{\rm op}}}}^T\left( f(W_0)-f^*\right)+\sum_{t=0}^{T-1}\pth{1-\frac{\eta}{D_{{\rm op}}}}^{T-1-t}\frac{\eta^2L_*}{2}\\
        \leq&\pth{1-\frac{\eta}{D_{{\rm op}}}}^T( f(W_{0})-f^*)+\frac{\eta L_* D_\op}{2}.
    \end{align*}
Thus, to reach the precision $f(W_T)-f^*\leq \epsilon$, we can take $\eta=O(\frac{\epsilon}{L_*D_{{\rm op}}})$, and the complexity is $O(L_*D_{{\rm op}}^2 \epsilon^{-1}\text{log}\frac{\Delta}{\epsilon})$, where $\Delta=f(W_0)-f^*$.


\textbf{Adaptive stepsize}

    By the $L_*$ spectral norm Lipschitz smoothness of $f$ and setting $\eta_{t}=\frac{\|\nabla f(W_{t})\|_*}{L_*}$, we have
    \begin{align}
        f(W_{t+1})&\leq f(W_{t})+\langle\nabla f(W_{t}),W_{t+1}-W_{t}\rangle +\frac{L_*}{2}\|W_{t+1}-W_{t}\|_{{\rm op}}^2 \notag\\
        &=f(W_{t})-\eta_{t}\|\nabla f(W_{t})\|_*+\frac{L_*\eta_{t}^2}{2} \notag\\
        &=f(W_{t})-\frac{\|\nabla f(W_{t})\|_*^2}{2L_*} .\label{eq: L*smooth}
    \end{align}
From the star-convex property, we have
\begin{align} \label{eq: L*convex}
    \Delta_t:=f(W_t)-f^*\leq \langle \nabla f(W_t), W_t-W^*\rangle \leq \|\nabla f(W_t)\|_*\|W_t-W^*\|_{{\rm op}}.
\end{align}

Combining \Cref{eq: L*smooth} and \Cref{eq: L*convex}, we obtain
$$\Delta_{t+1}\leq \Delta_{t}-\frac{1}{2L_*\|W_t-W^*\|^2_{{\rm op}}}\Delta_{t}^2.$$

Then we have
$$\frac{1}{\Delta_{t+1}}\geq \frac{1}{\Delta_{t}}+\frac{\Delta_{t}}{2L_*\|W_t-W^*\|_{{\rm op}}^2 \Delta_{t+1}}.$$

Using $\|W_t-W^*\|_{{\rm op}}\leq D_{{\rm op}}$, then we can sum above inequality to obtain
$$\frac{1}{\Delta_{t}}\geq \frac{1}{\Delta_0}+\sum_{i=1}^t \frac{\Delta_{t-1}}{2L_*D_{{\rm op}}^2 \Delta_{t}} \geq  \frac{1}{\Delta_0}+\frac{t}{2L_*D_{{\rm op}}^2},$$
where we use $\frac{\Delta_t}{\Delta_{t-1}}\geq 1$.

After rearranging terms, we obtain 
$$f(W_t)-f^*\leq \frac{2L_*(f(W_0)-f^*)D_{{\rm op}}^2}{2L_*D_{{\rm op}}^2+t(f(W_0)-f^*)}.$$
\end{proof}


\subsection{Convergence analysis with \Cref{ass: third}}\label{app: convex J}

\begin{theorem}
 Under \Cref{ass: convex}, \Cref{ass: third} and \Cref{ass: bounded}, if we apply \Cref{alg: muon_deterministic} with $\eta_t=\eta$, we have
    \begin{align*}
        f(W_{T})-f^*
        \leq&\pth{1-\frac{\eta}{D_{{\rm op}}}}^T( f(W_{0})-f^*)+\sum_{t=0}^{T-1}\pth{1-\frac{\eta}{D_{{\rm op}}}}^{T-1-t}\frac{\eta^2 J_t}{2}+\frac{s\eta^2 D_\op r^{3/2}}{6}.
    \end{align*}
where  $J_t=\mathsf{vec}(U_tV_t^\top)^\top H_t \mathsf{vec}(U_tV_t^\top)$, $H_t=\nabla^2f_v(\mathsf{vec}(W_t))$, and $f_v(\mathsf{vec}(W_t))=f(W_t)$.  

Denote $\Delta=f(W_0)-f^*$ and $\hat{J}=\frac{1}{T}\sum_{t=0}^{T-1}|J_t|$. We have
    \begin{align*}
        f(W_T)-f^*&\leq \pth{1-\frac{\eta}{D_{{\rm op}}}}^T\Delta+\frac{\eta^2 \hat{J}T}{2}+\frac{s\eta^2 D_\op r^{3/2}}{6}.
    \end{align*}

 When $\hat{J}>0$, we can set $\eta=\min\sth{\frac{D_{{\rm op}}}{T}\log\pth{\frac{T \Delta}{ D_{{\rm op}}^2\hat{J}}}, D_\op}$. We have
    \begin{align*}
        f(W_T)-f^*\leq& \frac{D_{{\rm op}}^2\hat{J}}{T}+\frac{D_{{\rm op}}^2\hat{J}}{2T}\qth{\log\pth{\frac{T \Delta}{ D_{{\rm op}}^2\hat{J}}}}^2+\frac{sr^{3/2}D_{{\rm op}}^3}{6T^2}\qth{\log\pth{\frac{T \Delta}{ D_{{\rm op}}^2\hat{J}}}}^2\\
        \leq&\tilde{O}\pth{\frac{D_{{\rm op}}^2\hat{J}}{T}}.
    \end{align*}
When $\hat{J}=0$, we can set $\eta=\min\sth{\frac{D_{{\rm op}}}{T}\log\pth{\frac{T^2 \Delta}{ D_{{\rm op}}^3 sr^{3/2}}}, D_\op}$. We have
    \begin{align*}
        f(W_T)-f^*\leq& \frac{sr^{3/2}D_{{\rm op}}^3}{T^2}+\frac{sr^{3/2}D_{{\rm op}}^3}{6T^2}\qth{\log\pth{\frac{T^2 \Delta}{ D_{{\rm op}}^3 sr^{3/2}}}}^2\\
        \leq&\tilde{O}\pth{\frac{sr^{3/2}D_{{\rm op}}^3}{T^2}}.
    \end{align*}
\end{theorem}
\begin{proof}
According to \Cref{eq: J descent}, we have
\begin{align}\label{eq: J1}
    f(W_{t+1})-f(W_t)\leq&-\eta\|\nabla f(W_t)\|_*+\frac{\eta^2 J_t}{2}+\frac{s\eta^3r^{3/2}}{6}
\end{align}

Moreover, according to \eqref{eq: star-convex}, we have
\begin{align*}
    -\|\nabla f(W_t)\|_*&\leq -\frac{f(W_t)-f^*}{D_{{\rm op}}}
\end{align*}


Combine \eqref{eq: J1} and \eqref{eq: star-convex}, we can obtain
    \begin{align*}
        f(W_{t+1})-f^*\leq \pth{1-\frac{\eta}{D_{{\rm op}}}}( f(W_{t})-f^*)+\frac{\eta^2 J_t}{2}+\frac{s\eta^3r^{3/2}}{6}.
    \end{align*}
Then, we have
    \begin{align*}
        f(W_{T})-f^*\leq& \pth{1-\frac{\eta}{D_{{\rm op}}}}^T\left( f(W_0)-f^*\right)+\sum_{t=0}^{T-1}\pth{1-\frac{\eta}{D_{{\rm op}}}}^{T-1-t}\frac{\eta^2J_t}{2}+\sum_{t=0}^{T-1}\pth{1-\frac{\eta}{D_{{\rm op}}}}^{T-1-t}\frac{s\eta^3r^{3/2}}{6}\\
        \leq&\pth{1-\frac{\eta}{D_{{\rm op}}}}^T( f(W_{0})-f^*)+\sum_{t=0}^{T-1}\pth{1-\frac{\eta}{D_{{\rm op}}}}^{T-1-t}\frac{\eta^2 J_t}{2}+\frac{s\eta^2 D_\op r^{3/2}}{6}.
    \end{align*}
Denote $\Delta=f(W_0)-f^*$ and $\tilde{J}=\sum_{t=0}^{T-1}\pth{1-\frac{\eta}{D_{{\rm op}}}}^{T-1-t}\frac{\eta}{D_\op}J_t$. We have
\begin{align*}
        f(W_T)-f^*&\leq \pth{1-\frac{\eta}{D_{{\rm op}}}}^T\Delta+\frac{\eta D_\op\tilde{J}}{2}+\frac{s\eta^2 D_\op r^{3/2}}{6}.
\end{align*}
Thus, the convergence complexity can be depending on $\tilde{J}$, which can be viewed as a weighted average of $J_t$.

In experiments, we found that usually $J_t>0$. Note that if $f$ is strict convex and if $U_tV_t^\top\neq 0$, then $J_t$ is strictly larger than 0. Thus, to get a more illustrative and clearer result, if we denote $\hat{J}=\frac{1}{T}\sum_{t=0}^{T-1}|J_t|$, then we have
    \begin{align*}
        f(W_T)-f^*&\leq \pth{1-\frac{\eta}{D_{{\rm op}}}}^T\Delta+\frac{\eta^2 \hat{J}T}{2}+\frac{s\eta^2 D_\op r^{3/2}}{6}.
    \end{align*}
 When $\hat{J}>0$, we can set $\eta=\min\sth{\frac{D_{{\rm op}}}{T}\log\pth{\frac{T \Delta}{ D_{{\rm op}}^2\hat{J}}}, D_\op}$. We have
    \begin{align*}
        f(W_T)-f^*\leq& \frac{D_{{\rm op}}^2\hat{J}}{T}+\frac{D_{{\rm op}}^2\hat{J}}{2T}\qth{\log\pth{\frac{T \Delta}{ D_{{\rm op}}^2\hat{J}}}}^2+\frac{sr^{3/2}D_{{\rm op}}^3}{6T^2}\qth{\log\pth{\frac{T \Delta}{ D_{{\rm op}}^2\hat{J}}}}^2\\
        \leq&\tilde{O}\pth{\frac{D_{{\rm op}}^2\hat{J}}{T}}.
    \end{align*}
When $\hat{J}=0$, we can set $\eta=\min\sth{\frac{D_{{\rm op}}}{T}\log\pth{\frac{T^2 \Delta}{ D_{{\rm op}}^3 sr^{3/2}}}, D_\op }$. We have
    \begin{align*}
        f(W_T)-f^*\leq& \frac{sr^{3/2}D_{{\rm op}}^3}{T^2}+\frac{sr^{3/2}D_{{\rm op}}^3}{6T^2}\qth{\log\pth{\frac{T^2 \Delta}{ D_{{\rm op}}^3 sr^{3/2}}}}^2\\
        \leq&\tilde{O}\pth{\frac{sr^{3/2}D_{{\rm op}}^3}{T^2}}.
    \end{align*}
\end{proof}








\subsection{Convergence analysis with \Cref{ass: smooth}}\label{app: convex L}


\begin{theorem}\label{thm: convex_L}
 Under \Cref{ass: convex}, \Cref{ass: smooth}, and \Cref{ass: bounded}, if we apply \Cref{alg: muon_deterministic} with $\eta_t=\eta$, then
    \begin{align*}
        f(W_T)-f^*\leq \pth{1-\frac{\eta}{D_\op}}^T(f(W_0)-f^*)+\frac{rLD_{{\rm op}}\eta}{2}.
    \end{align*}
    Thus, to reach the precision $f(W_T)-f^*\leq \epsilon$, we can take $\eta=O(\frac{\epsilon}{rLD_{{\rm op}}})$, and the complexity is $O(rLD_{{\rm op}}^2 \epsilon^{-1}\text{log}\frac{\Delta}{\epsilon})$, where $\Delta=f(W_0)-f^*$.

Moreover, if we apply \Cref{alg: muon_deterministic} with adaptive learning rates $\eta_t=\frac{\|\nabla f(W_{t})\|_*}{rL}$, we have
    \begin{align*}
        f(W_t)-f^*\leq \frac{2rL(f(W_0)-f^*)D_{{\rm op}}^2}{2rLD_{{\rm op}}^2+t(f(W_0)-f^*)}.
    \end{align*}
Thus, to reach the precision $f(W_T)-f^*\leq \epsilon$, the complexity is $O(rLD_{{\rm op}}^2\epsilon^{-1})$.

\end{theorem}


\begin{proof}

\textbf{Constant stepsize}


First, by the $L$ Frobenius norm Lipschitz smoothness of $f$, we have
    \begin{align}\nonumber
        f(W_{t+1})&\leq f(W_{t})+\langle\nabla f(W_{t}),W_{t+1}-W_{t}\rangle +\frac{L}{2}\|W_{t+1}-W_{t}\|_\F^2\\
         \label{eq: convex L}
        &\leq f(W_{t})-\eta_{t}\|\nabla f(W_{t})\|_*+\frac{rL\eta_{t}^2}{2}
    \end{align}

Then, according to \eqref{eq: star-convex}, we have
\begin{align*}
    -\|\nabla f(W_t)\|_*&\leq -\frac{f(W_t)-f^*}{D_{{\rm op}}}
\end{align*}

Set $\eta=\eta$ and combine \eqref{eq: convex L} and \eqref{eq: star-convex}. We have
\begin{align*}
    f(W_{t+1})-f^*\leq \pth{1-\frac{\eta}{D_{{\rm op}}}}( f(W_{t})-f^*)+\frac{rL\eta^2}{2},
\end{align*}
and
    \begin{align*}
        f(W_{T})-f^*\leq& \pth{1-\frac{\eta}{D_{{\rm op}}}}^T\left( f(W_0)-f^*\right)+\sum_{t=0}^{T-1}\pth{1-\frac{\eta}{D_{{\rm op}}}}^{T-1-t}\frac{rL\eta^2}{2}\\
        \leq&\pth{1-\frac{\eta}{D_{{\rm op}}}}^T( f(W_{0})-f^*)+\frac{rL D_\op\eta}{2}.
    \end{align*}
Thus, to reach the precision $f(W_T)-f^*\leq \epsilon$, we can take $\eta=O(\frac{\epsilon}{rLD_{{\rm op}}})$, and the complexity is $O(rLD_{{\rm op}}^2 \epsilon^{-1}\text{log}\frac{\Delta}{\epsilon})$, where $\Delta=f(W_0)-f^*$.


\textbf{Adaptive stepsize}

    By the $L$ spectral norm Lipschitz smoothness of $f$ and setting $\eta_{t}=\frac{\|\nabla f(W_{t})\|_*}{rL}$, we have
    \begin{align}
        f(W_{t+1})&\leq f(W_{t})+\langle\nabla f(W_{t}),W_{t+1}-W_{t}\rangle +\frac{L}{2}\|W_{t+1}-W_{t}\|_\F^2 \notag\\
        &\leq f(W_{t})-\eta_{t}\|\nabla f(W_{t})\|_*+\frac{rL\eta_{t}^2}{2} \notag\\
        &=f(W_{t})-\frac{\|\nabla f(W_{t})\|_*^2}{2rL} .\label{eq: Lsmooth}
    \end{align}
From the star-convex property, we have
\begin{align} \label{eq: convex}
    \Delta_t:=f(W_t)-f^*\leq \langle \nabla f(W_t), W_t-W^*\rangle \leq \|\nabla f(W_t)\|_*\|W_t-W^*\|_{{\rm op}}.
\end{align}

Combining \Cref{eq: Lsmooth} and \Cref{eq: convex}, we obtain
$$\Delta_{t+1}\leq \Delta_{t}-\frac{1}{2rL\|W_t-W^*\|^2_{{\rm op}}}\Delta_{t}^2.$$

Then we have
$$\frac{1}{\Delta_{t+1}}\geq \frac{1}{\Delta_{t}}+\frac{\Delta_{t}}{2rL\|W_t-W^*\|_{{\rm op}}^2 \Delta_{t+1}}.$$

Using $\|W_t-W^*\|_{{\rm op}}\leq D_{{\rm op}}$, we can sum above inequality to obtain
$$\frac{1}{\Delta_{t}}\geq \frac{1}{\Delta_0}+\sum_{i=1}^t \frac{\Delta_{t-1}}{2rLD_{{\rm op}}^2 \Delta_{t}} \geq  \frac{1}{\Delta_0}+\frac{t}{2rLD_{{\rm op}}^2},$$
where we use $\frac{\Delta_t}{\Delta_{t-1}}\geq 1$.

After rearranging terms, we obtain 
$$f(W_t)-f^*\leq \frac{2rL(f(W_0)-f^*)D_{{\rm op}}^2}{2rLD_{{\rm op}}^2+t(f(W_0)-f^*)}.$$
\end{proof}


\section{Experimental settings}\label{app: exp}
Experiments of \Cref{fig:comparison} and \Cref{fig:J} are conducted on NVIDIA H100 GPUs. Experiments of \Cref{figure: q} are conducted on Intel(R) Core(TM) i9-14900HX.

In \Cref{fig:comparison} (a), we randomly select a fixed subset of 100 samples from CIFAR-10 and train a fully connected neural network (\Cref{tab: net cifar10}) on this subset, serving as the deterministic setting. The learning rates for GD, Adam, Muon (using Newton–Schulz iterations with momentum), Muon\_withoutM (without momentum), and Muon\_SVD (\Cref{alg: muon}) are tuned from the set $\{1e^{-4}, 5e^{-4}, 1e^{-3}, 5e^{-3}, 1e^{-2}, \allowbreak 5e^{-2}, 1e^{-1}\}$. We conduct experiments with five different random seeds, and report the average results along with one standard deviation in \Cref{fig:comparison} (a). In \Cref{fig:comparison} (b), we train the same neural network using stochastic batches sampled from the entire CIFAR-10 training set, with a batch size of 120. The learning rates for GD, Muon, Muon\_withoutM, and Muon\_SVD are tuned from $\{1e^{-3}, 5e^{-3}, 1e^{-2}, 5e^{-2}, 1e^{-1}\}$, while the learning rate for Adam is tuned from $\{1e^{-4}, 5e^{-4}, 1e^{-3}, 5e^{-3}\}$. The model is trained for 5 epochs, and after each epoch, we evaluate the loss on the entire CIFAR-10 training set. The results are presented in \Cref{fig:comparison} (b).

In \Cref{fig:J}, we randomly select a fixed subset of 60 samples from MNIST. We then train a fully connected neural network (\Cref{tab: net mnist}) with three matrix parameters ($W^1 \in \mathbb{R}^{128 \times 784}$, $W^2 \in \mathbb{R}^{64 \times 128}$, $W^3 \in \mathbb{R}^{10 \times 64}$) on this subset using GD and Muon (\Cref{alg: muon_deterministic}). We first tune the learning rates for GD and Muon from the set $\{1e^{-3}, 5e^{-3}, 1e^{-2}, 5e^{-2}, 1e^{-1}, 5e^{-1}, 1\}$, and find that the optimal learning rate for both is 0.1. Using the selected learning rate, we optimize the neural network with GD and Muon (\Cref{alg: muon_deterministic}), respectively, and record the loss, $J_t$, $L_t$, $\|\nabla f(W_t)\|_*^2$, and $\|\nabla f(W_t)\|_\F^2$ throughout the optimization process. These quantities are computed with respect to $W^2$, i.e., $\nabla f = \nabla_{W^2} f(W^1_t, W^2_t, W^3_t)$ and $\nabla^2 f = \nabla^2_{\mathsf{vec}(W^2)\mathsf{vec}(W^2)} f_v(\mathsf{vec}(W^1_t), \mathsf{vec}(W^2_t), \mathsf{vec}(W^3_t))$, where $f_v(\mathsf{vec}(W^1_t), \mathsf{vec}(W^2_t), \mathsf{vec}(W^3_t))=f(W^1_t, W^2_t, W^3_t)$. The results are shown in \Cref{fig:J}.

In \Cref{figure: q}(a)(b), we consider the quadratic function $f(W)=\frac{1}{2}Tr((W-W_{\text{opt}})Q(W-W_{\text{opt}})')$, $W\in \mathbb{R}^{15\times 20}, Q\in \mathbb{R}^{15\times 15}$, where $W_{\text{opt}}$ is randomly chosen and $Q$ is chosen with an ill condition number. Then, we apply GD and Muon to optimize this function, both start from the $W_0=0$ with 4000 iterations. We choose the optimal constant stepsize $\frac{1}{L}$ for GD and choose the stepsize for Muon such that Muon can converge in 4000 iterations with the best function value.  For each iteration of both algorithms, we record the difference in function value from the optimum and the spectral norm error to the optimal point. The results are shown in \Cref{figure: q}(a) and (b). In \Cref{figure: q}(c), we compare the key constant in convergence analysis under quadratic function with ill-conditioned $Q$. We choose $W_{\text{opt}}\sim U(-50,50)$, which means each element of $W_{\text{opt}}$ is i.i.d. random variables drawn from a continuous uniform distribution. Then, we estimate the key constants $D_{{\rm op}}^2L_*$ and $D_\F^2L$, where we choose the initial point as $W_0=0$. We calculate the ratios $\frac{D_\F^2L}{D_{{\rm op}}^2L_*}$ over $10^4$ random samples. The results are shown in \Cref{figure: q}(c).

