\section{Muon with Newton-Schulz iterations}\label{app: muon ns}
As discussed in \Cref{section: muon}, computing SVD is usually expensive in practice, especially when the dimensions are large. Therefore, a common implementation of Muon employs the Newton-Schulz iterations \cite{bernstein2024old, jordan2024muon} to approximate the orthogonalization process (\Cref{alg: muon ns}). In the original paper of Muon \citep{jordan2024muon}, they define their Newton-Schulz iterations (line 6 in \Cref{alg: muon ns}) in the following way. First, the input $M_t$ will be normalized as $X_0=M_t/\|M_t\|_\F$. Then, $X_k$ is computed from $X_{k-1}$ according to the following update rule:
\begin{align*}
    X_k=aX_{k-1}+b(X_{k-1}X_{k-1}^\top)X_{k-1}+c(X_{k-1}X_{k-1}^\top)^2X_{k-1}.
\end{align*}
Following the analysis in \cite{jordan2024muon} and 
supposing the SVD of $M_t$ is $U_tS_tV_t^\top$, we have $X_{0}=U_t\Bar{S}_tV_t^\top$, where $\Bar{S}_t=S_t/\|S_t\|_\F$. We can note that
\begin{align*}
    X_1=&aX_{0}+b(X_{0}X_{0}^\top)X_{0}+c(X_{0}X_{0}^\top)^2X_{0}\\
    =&(aI+bU\Bar{S}^2U^\top+cU\Bar{S}^4U^\top)U\Bar{S}V^\top\\
    =&U(a\Bar{S}+b\Bar{S}^3+c\Bar{S}^5)V^\top.
\end{align*}
Define $\varphi(x)=ax+bx^3+cx^5$. Then after $k$ iterations, the output is $O_t=X_k=U_t\varphi^k(\Bar{S}_t)V_t^\top$. In \cite{jordan2024muon}, they set $k=5$, $a=3.4445$, $b=-4.7750$, and $c=2.0315$. Note that $\Bar{S}_t=S_t/\|S_t\|_\F$ is normalized; thus, its singular values are in $[0,1]$. We can plot $\varphi^5(x)$ in $[0,1]$ and get \Cref{fig:ns}. Note that there is a steep jump around $x=0$ in \Cref{fig:ns} and if we define a threshold $\varepsilon$ such that for $x\in[\varepsilon, 1]$, $\varphi^5(x)\in [0.65, 1.25]$, we can have that this threshold $\varepsilon$ is very small and most function values of $\varphi^5(x)$ lie in $[0.65, 1.25]$. Thus, $O_t=U_t\varphi^k(\Bar{S}_t)V_t^\top$ serves as a low-cost yet effective approximation to $U_tV_t^\top$.



\begin{algorithm}
    \caption{Muon with Newton–Schulz iterations}
    \label{alg: muon ns}
    \begin{algorithmic}[1]
        \State \textbf{Input}: Initial weights $W_0$, learning rate schedule $\{\eta_t\}$, $\beta\in [0,1)$, batch size $B$ 
        \For{$t = 0, 1, \ldots, T-1$}
            \State Sample batch $\{\xi_{t,i}\}_{i=1}^B$ uniformly
            \State $G_t = \frac{1}{B} \sum_{i=1}^B \nabla f(W_t; \xi_{t,i})$ (or $G_t =\nabla f(W_t)$ in the deterministic setting)
            \State If $t>0$, $M_t = \beta M_{t-1} + (1 - \beta) G_t$. If $t=0$, $M_0=G_0$.
            \State $O_t = \text{NewtonSchulz}(M_t)$
            \State $W_{t+1} = W_t - \eta_t O_t$
        \EndFor
    \end{algorithmic}
\end{algorithm}


